INSERT INTO `brands` VALUES (1,'sika','SIK','Sika','brands/sika/logo.svg','[\"ind.sika.com\", \"sika.com\"]','{\"price_band\": {\"value\": {\"unit\": \"₹/kg\", \"lowest\": 330, \"highest\": 440}, \"provenance\": \"estimated\", \"source_url\": null}, \"primary_use\": {\"value\": \"Structural bonding and epoxy repair in concrete rehabilitation\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"special_use\": {\"value\": \"Segmental bridge adhesives, carbon-fibre plate bonding and metro tunnel segment sealing\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"secondary_use\": {\"value\": \"Waterproofing, sealants and industrial flooring\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"parent_company\": {\"value\": \"Sika AG, Baar, Switzerland (listed on SIX Swiss Exchange; India operations through Sika India Pvt. Ltd., Kolkata)\", \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Sika_AG\"}, \"market_coverage\": {\"value\": \"Subsidiaries in 103 countries and over 400 factories; ~33,700 employees and CHF 11.2 bn revenue (2025). In India, national dealer coverage with a strong presence in metro infrastructure, industrial and repair contracting\", \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Sika_AG\"}, \"region_strengths\": {\"value\": {\"weak\": \"Deep rural retail\", \"rural\": \"weak\", \"urban\": \"strong\", \"strong\": \"Pan-India, led by metro and industrial corridors\", \"balanced\": \"South\"}, \"provenance\": \"ai_filled\", \"source_url\": null}, \"year_established\": {\"value\": 1910, \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Sika_AG\"}, \"novice_preference\": {\"value\": \"Low. Rarely bought by homeowners — sold through project counters and specialist repair dealers rather than hardware shops, and the pack sizes start at 3 kg.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"product_portfolio\": {\"value\": \"Concrete admixtures, structural epoxy adhesives and anchors (Sikadur), repair mortars (SikaTop, Sika MonoTop), waterproofing membranes and liquid systems (Sikalastic, SikaProof), sealants (Sikaflex), industrial and decorative flooring (Sikafloor), roofing and tile-fixing systems\", \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Sika_AG\"}, \"bulk_discount_note\": {\"value\": \"30 kg units carry the best per-kg rate; a further 5–8 % is normal on multi-unit site orders released against a single project code.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"dealer_margin_note\": {\"value\": \"Roughly 10–15 % on construction-chemical lines, thinner than on cement but supported by higher ticket value per pack.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"engineer_user_rating\": {\"value\": \"4.6/5 (typical among structural and repair consultants)\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"top_preference_order\": {\"value\": [\"Sika\", \"Fosroc\", \"MC-Bauchemie\", \"BASF Master Builders\", \"Pidilite (Dr. Fixit)\"], \"provenance\": \"ai_filled\", \"source_url\": null}, \"contractor_preference\": {\"value\": \"First choice for specified structural repair, retrofitting and strengthening work; contractors trust the Sikadur name on tender submissions even where a cheaper local epoxy would pass.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"quality_strength_note\": {\"value\": \"Datasheet-led brand: every product ships with a full technical data sheet and an India-specific formulation where the climate demands it. Sikadur-31 IN is rated to +40 °C rather than the +30 °C global variant, which is why it holds up on South Indian sites.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"building_type_strengths\": {\"value\": {\"roads\": \"moderate\", \"bridges\": \"strong\", \"low_rise\": \"strong\", \"mid_rise\": \"strong\", \"high_rise\": \"strong\", \"dams_metro\": \"strong\", \"skyscrapers\": \"strong\", \"individual_houses\": \"moderate\"}, \"provenance\": \"ai_filled\", \"source_url\": null}, \"project_vs_retail_cost_note\": {\"value\": \"Project-rate supply on a Sika India schedule typically lands 12–18 % under counter rate for orders above ~100 kg; retail counter buyers in Hyderabad and Vijayawada pay the top of the band.\", \"provenance\": \"ai_filled\", \"source_url\": null}}','2026-08-22 06:03:31','2026-08-22 07:52:07'),(2,'fosroc','FOS','Fosroc','brands/fosroc/logo.svg','[\"fosroc.com\"]','{\"price_band\": {\"value\": {\"unit\": \"₹/kg\", \"lowest\": 750, \"highest\": 1650}, \"provenance\": \"estimated\", \"source_url\": null}, \"primary_use\": {\"value\": \"Grouting and anchoring for industrial plant and structural steel\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"special_use\": {\"value\": \"Crack and honeycomb injection in high-strength concrete, and chemically resistant flooring in refineries and plating works\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"secondary_use\": {\"value\": \"Concrete repair, protective coatings and waterproofing\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"parent_company\": {\"value\": \"Compagnie de Saint-Gobain — completed its purchase of Fosroc on 2 February 2025; India operations run through Fosroc Chemicals (India) Pvt. Ltd., Bangalore\", \"provenance\": \"fetched\", \"source_url\": \"https://www.fosroc.com/news/saint-gobain-completes-the-acquisition-of-fosroc\"}, \"market_coverage\": {\"value\": \"Around 25 locations and roughly 3,000 employees worldwide, with its strongest footprint in India, the Middle East and Asia-Pacific; revenue about USD 487 million (2024). In India, head office in Bangalore with regional offices in Chennai, Mumbai, Noida and Kolkata\", \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Fosroc\"}, \"region_strengths\": {\"value\": {\"weak\": \"Rural retail\", \"rural\": \"weak\", \"urban\": \"strong\", \"strong\": \"South and West India, Middle East\", \"balanced\": \"North\"}, \"provenance\": \"ai_filled\", \"source_url\": null}, \"year_established\": {\"value\": 1972, \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Fosroc\"}, \"novice_preference\": {\"value\": \"Low. This is a project-counter brand — the pack sizes, technical language and price point put it outside the reach of a first-time homeowner buyer.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"product_portfolio\": {\"value\": \"Concrete admixtures (Conplast), cementitious and epoxy grouts and anchors (Conbextra, Lokfix), concrete repair mortars (Renderoc, Nitomortar), bonding agents and primers (Nitobond, Nitoprime), waterproofing membranes, joint sealants (Nitoseal, Thioflex), protective and anti-carbonation coatings (Dekguard) and industrial flooring (Nitoflor)\", \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Fosroc\"}, \"bulk_discount_note\": {\"value\": \"Larger Conbextra EP10 M and free-flow packs bought by the carton attract 8–12 % off single-pack rate; injection work priced per site rather than per pack.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"dealer_margin_note\": {\"value\": \"Roughly 12–18 % at the authorised-dealer level, with wider spreads on low-volume epoxy specialities than on admixtures.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"engineer_user_rating\": {\"value\": \"4.5/5 (typical among repair and industrial-project engineers)\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"top_preference_order\": {\"value\": [\"Fosroc\", \"Sika\", \"BASF Master Builders\", \"MC-Bauchemie\", \"Pidilite (Dr. Fixit)\"], \"provenance\": \"ai_filled\", \"source_url\": null}, \"contractor_preference\": {\"value\": \"The default for machine-base and base-plate grouting on industrial projects; contractors carry Conbextra on site as a matter of habit and rarely substitute it mid-contract.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"quality_strength_note\": {\"value\": \"Fosroc\'s strength is the specification: Conbextra, Renderoc and Nitobond are written into Indian tender documents by name, and the India-specific TDS carries the numbers a consultant needs to sign off. Conbextra EP10\'s own datasheet writes the specification clause for you.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"building_type_strengths\": {\"value\": {\"roads\": \"moderate\", \"bridges\": \"strong\", \"low_rise\": \"moderate\", \"mid_rise\": \"strong\", \"high_rise\": \"strong\", \"dams_metro\": \"strong\", \"skyscrapers\": \"strong\", \"individual_houses\": \"weak\"}, \"provenance\": \"ai_filled\", \"source_url\": null}, \"project_vs_retail_cost_note\": {\"value\": \"Project supply against a Fosroc India rate contract typically runs 15–25 % below the IndiaMART counter quotes, which vary widely by city; Proddatur and Ludhiana quotes sit at the top of the band, Ahmedabad and Mumbai at the bottom.\", \"provenance\": \"ai_filled\", \"source_url\": null}}','2026-08-22 06:03:31','2026-08-22 07:51:58'),(3,'pidilite','PID','Pidilite (Dr. Fixit)','brands/pidilite/logo.png','[\"drfixit.co.in\", \"pidilite.com\"]','{\"price_band\": {\"value\": {\"unit\": \"₹/kg\", \"lowest\": 575, \"highest\": 950}, \"provenance\": \"estimated\", \"source_url\": null}, \"primary_use\": {\"value\": \"Waterproofing of roofs, walls, bathrooms and tanks\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"special_use\": {\"value\": \"Structural epoxy crack injection in slabs, walls, water tanks and sea walls\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"secondary_use\": {\"value\": \"Concrete repair, crack filling and tile fixing\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"parent_company\": {\"value\": \"Pidilite Industries Limited, Mumbai — founded by Balvant Parekh; the Parekh family holds about 70 %. Dr. Fixit is the Construction Chemicals Division house brand\", \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Pidilite_Industries\"}, \"market_coverage\": {\"value\": \"Pan-India, with revenue of about ₹13,094 crore (US$1.4 bn, 2025) and the deepest retail distribution of any Indian construction-chemicals brand; joint ventures with Litokol and Tenax extend the construction-chemistry range\", \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Pidilite_Industries\"}, \"region_strengths\": {\"value\": {\"weak\": \"Large international-spec infrastructure tenders\", \"rural\": \"strong\", \"urban\": \"strong\", \"strong\": \"Pan-India retail, especially West and South\", \"balanced\": \"North and East\"}, \"provenance\": \"ai_filled\", \"source_url\": null}, \"year_established\": {\"value\": 1959, \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Pidilite_Industries\"}, \"novice_preference\": {\"value\": \"Highest of the three brands. Dr. Fixit is the name a homeowner already knows, so the 1 kg and 3 kg packs sell across the counter in a way Sika and Fosroc packs do not.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"product_portfolio\": {\"value\": \"Fevicol, Fevikwik, Fevigum, Fevicryl, M-Seal, Dr. Fixit waterproofing and construction chemicals, Roff tile adhesives and grouts, Fevitite epoxy adhesives, D-klog, Cyclo, Ranipal and Hobby Ideas\", \"provenance\": \"fetched\", \"source_url\": \"https://en.wikipedia.org/wiki/Pidilite_Industries\"}, \"bulk_discount_note\": {\"value\": \"The 3 kg pack is roughly 10–15 % cheaper per kg than the 1 kg; carton lots of 3 kg packs attract a further 5–10 % on project orders.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"dealer_margin_note\": {\"value\": \"Around 15–20 % at retail on construction-chemical lines — wider than cement, and the reason Dr. Fixit is pushed hard at the counter.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"engineer_user_rating\": {\"value\": \"4.3/5 (typical among repair contractors and site engineers)\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"top_preference_order\": {\"value\": [\"Pidilite (Dr. Fixit)\", \"Fosroc\", \"Sika\", \"Asian Paints SmartCare\", \"BASF Master Builders\"], \"provenance\": \"ai_filled\", \"source_url\": null}, \"contractor_preference\": {\"value\": \"Very high for waterproofing and general repair; on structural crack injection the Dr. Fixit pack is chosen where availability and price matter more than a named international specification.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"quality_strength_note\": {\"value\": \"Pidilite\'s edge is reach and support rather than laboratory ceiling: the Dr. Fixit Advice Centre, a dense dealer network and a technical library that publishes full BS 6319 test results mean a small contractor in a district town can buy and use a structural epoxy correctly.\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"building_type_strengths\": {\"value\": {\"roads\": \"moderate\", \"bridges\": \"moderate\", \"low_rise\": \"strong\", \"mid_rise\": \"strong\", \"high_rise\": \"moderate\", \"dams_metro\": \"moderate\", \"skyscrapers\": \"moderate\", \"individual_houses\": \"strong\"}, \"provenance\": \"ai_filled\", \"source_url\": null}, \"project_vs_retail_cost_note\": {\"value\": \"Project rates through a Pidilite construction-chemicals distributor typically run 15–20 % under the retail counter price; Hyderabad and Vijayawada counters sit mid-band.\", \"provenance\": \"ai_filled\", \"source_url\": null}}','2026-08-22 06:03:31','2026-08-22 07:52:07'),(4,'ceasefire','CEA','Ceasefire',NULL,'[\"ceasefire.in\", \"ceasefireonlineshop.com\"]','{\"price_band\": {\"value\": {\"unit\": \"₹/unit\", \"lowest\": 1500, \"highest\": 25000}, \"provenance\": \"estimated\", \"source_url\": null}, \"primary_use\": {\"value\": \"First-aid firefighting in homes, offices, shops, showrooms and vehicles\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"special_use\": {\"value\": \"Server rooms and electrical panel rooms, where the clean-agent variants of the same range are specified instead of powder\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"secondary_use\": {\"value\": \"Statutory fire-safety compliance for occupancy certificates and fire NOC in AP/Telangana\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"parent_company\": {\"value\": \"Ceasefire Industries Pvt. Ltd.\", \"provenance\": \"fetched\", \"source_url\": \"https://www.ceasefireonlineshop.com/products/abc-powder-map90-4kg\"}, \"market_coverage\": {\"value\": \"Pan-India direct sales, service and refilling network with a large branded retail and e-commerce presence; strong urban penetration in Hyderabad, Vijayawada and Visakhapatnam\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"region_strengths\": {\"value\": {\"weak\": \"Deep rural markets\", \"rural\": \"moderate\", \"urban\": \"strong\", \"strong\": \"Pan-India, especially metro and tier-1 cities\", \"balanced\": \"South India including Andhra Pradesh and Telangana\"}, \"provenance\": \"ai_filled\", \"source_url\": null}, \"year_established\": {\"value\": 2002, \"provenance\": \"fetched\", \"source_url\": \"https://www.ceasefire.in/about\"}, \"novice_preference\": {\"value\": \"Very high — the most recognised extinguisher brand for first-time home and car buyers, largely because of retail availability and advertising\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"product_portfolio\": {\"value\": \"Portable fire extinguishers (ABC powder, CO2, clean agent, foam, water), fire suppression systems, hydrant systems, fire alarm and detection systems\", \"provenance\": \"fetched\", \"source_url\": \"https://www.ceasefire.in/about\"}, \"bulk_discount_note\": {\"value\": \"Volume slabs generally start at 10 units; AMC and refill contracts are bundled with large orders\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"dealer_margin_note\": {\"value\": \"Dealer margins on branded portable extinguishers typically run 15–25%, with additional margin on annual refilling and servicing\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"engineer_user_rating\": {\"value\": \"4.4/5 — consistently rated the best-known consumer fire-safety brand in India; engineers cite build quality and the 10-year warranty\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"top_preference_order\": {\"value\": [\"Ceasefire\", \"Safex\", \"Kanex\", \"Minimax\", \"Omex\"], \"provenance\": \"ai_filled\", \"source_url\": null}, \"contractor_preference\": {\"value\": \"High for offices, retail, hospitality and residential towers where a certified brand name is specified; less common on price-driven industrial tenders\", \"provenance\": \"ai_filled\", \"source_url\": null}, \"quality_strength_note\": {\"value\": \"MAP 90 range carries dual certification — IS 15683 (BIS/ISI) plus EN 3 and PED, with LPCB approval, BSI Kitemark and CE marking; helium leak detection on every cylinder\", \"provenance\": \"fetched\", \"source_url\": \"https://www.ceasefire.in/product-page/abc-powder-portable-map-90-extinguishers\"}, \"building_type_strengths\": {\"value\": {\"roads\": \"moderate\", \"bridges\": \"weak\", \"low_rise\": \"strong\", \"mid_rise\": \"strong\", \"high_rise\": \"strong\", \"dams_metro\": \"moderate\", \"skyscrapers\": \"strong\", \"individual_houses\": \"strong\"}, \"provenance\": \"ai_filled\", \"source_url\": null}, \"project_vs_retail_cost_note\": {\"value\": \"Project and bulk institutional supply is typically 25–35% below the online-shop MRP; retail single-piece buyers pay close to list price\", \"provenance\": \"ai_filled\", \"source_url\": null}}','2026-08-22 06:03:31','2026-08-22 07:52:10'),(5,'safex-fire','SAF','Safex Fire','brands/safex-fire/logo.png','[\"safexfire.com\"]','{\"price_band\": {\"value\": {\"unit\": \"₹/unit\", \"lowest\": 900, \"highest\": 18000}, \"provenance\": \"estimated\", \"source_url\": null}, \"primar