DROP TABLE IF EXISTS `sku_images`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sku_images` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `sku_id` bigint NOT NULL,
  `position` tinyint NOT NULL,
  `role` enum('hero','angle','in_context','detail','pack_or_dimensions') NOT NULL,
  `alt` varchar(255) NOT NULL DEFAULT '',
  `source_url` text,
  `width` int DEFAULT NULL,
  `height` int DEFAULT NULL,
  `blurhash` varchar(64) DEFAULT NULL,
  `storage_key_original` varchar(255) NOT NULL,
  `placeholder` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `source_kind` enum('curated','official_page','official_pdf','distributor','unknown') NOT NULL DEFAULT 'unknown',
  `quality_score` decimal(3,2) DEFAULT NULL,
  `judge_json` json DEFAULT NULL,
  `cutout_key` varchar(255) DEFAULT NULL,
  `soft` tinyint(1) NOT NULL DEFAULT '0',
  `phash` varchar(16) DEFAULT NULL,
  `source_sha1` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sku_images_pos_uq` (`sku_id`,`position`),
  KEY `sku_images_quality_idx` (`quality_score`),
  CONSTRAINT `sku_images_sku_id_skus_id_fk` FOREIGN KEY (`sku_id`) REFERENCES `skus` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=404493 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
