--
-- Table structure for table `skus`
--

DROP TABLE IF EXISTS `skus`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `skus` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL,
  `sku_code` varchar(32) NOT NULL,
  `variant_label` varchar(120) NOT NULL DEFAULT '',
  `mrp` decimal(12,2) DEFAULT NULL,
  `selling_price` decimal(12,2) DEFAULT NULL,
  `price_provenance` enum('fetched','verified','estimated') NOT NULL DEFAULT 'estimated',
  `price_source_url` text,
  `price_note` varchar(255) DEFAULT NULL,
  `price_fetched_at` datetime DEFAULT NULL,
  `gst_rate` decimal(5,2) NOT NULL DEFAULT '18.00',
  `gst_needs_verification` tinyint(1) NOT NULL DEFAULT '0',
  `unit` varchar(24) NOT NULL DEFAULT 'piece',
  `pack_qty` decimal(10,3) NOT NULL DEFAULT '1.000',
  `stock_status` enum('in_stock','low','out_of_stock','preorder') NOT NULL DEFAULT 'in_stock',
  `short_description` varchar(200) NOT NULL DEFAULT '',
  `long_description` mediumtext,
  `key_specs` json NOT NULL DEFAULT (_utf8mb4'[]'),
  `spec_json` json DEFAULT NULL,
  `seo` json DEFAULT NULL,
  `hero_image_key` varchar(255) DEFAULT NULL,
  `blurhash` varchar(64) DEFAULT NULL,
  `rating_placeholder` decimal(2,1) NOT NULL DEFAULT '4.3',
  `official_url` text,
  `coverage` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `category_id` bigint DEFAULT NULL,
  `price_checked_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `skus_code_uq` (`sku_code`),
  KEY `skus_product_idx` (`product_id`),
  KEY `skus_price_idx` (`selling_price`),
  KEY `skus_cat_id_idx` (`category_id`,`id`),
  KEY `skus_cat_stock_id_idx` (`category_id`,`stock_status`,`id`),
  CONSTRAINT `skus_category_id_categories_id_fk` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `skus_product_id_products_id_fk` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1062541 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

